INSERT INTO `settings` (`Id`, `userId`, `version`, `name`, `contents`, `created_date`, `edited_date`) VALUES
(14, 0, 5, 'configuration', '{\n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \"CensoredWords\": [\"fuck\", \"bitch\", \"shit\", \"fag\", \"ussy\", \"cunt\", \"rape\", \"rapist\", \"dick\", \"cock\", \"ass\", \"penis\", \"vagina\", \"tits\", \"porn\", \"naked\", \"sex\", \"damn\", \"douche\", \"twat\", \"nigga\", \"nigger\", \"negro\", \"black\", \"white\", \"red\", \"yellow\", \"asian\"],\n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \"IsDeadVersion\": false,\n                                                                          \"UseLocalStorage\": false,\n                                                                          \"MirrorStorage\": false,\n                                                                  \n                                                                          \"MaxSquadSize\": 10,\n                                                                          \"MaxSquadWidth\": -1, // -1 Means match this to MaxSquadSize\n                                                                          \"MaxSquadHeight\": 10,\n                                                                          \"RotationMultiplier\": 16,\n                                                                          \n                                                                          \"HumanSide\": 2,\n                                                                          \"BeeSide\": 1,\n                                                                          \"DoesUserHaveController\": false,\n                                                                          \"StorageChunkSize\": 2500000, //Ensure that the results aren\'t sent to the server until the end of the level\n                                                                          \"StandardMaxTimeOnQueue\": 25, // seconds \n                                                                          \"TimeScale\": 1,\n                                                                          \n                                                                          \"AISquadPatrolTime\": 60,\n                                                                          \"AIPatrolMaxSize\": 100,\n                                                                          \"AIRandomMovementMaxDistance\": 200,\n                                                                          \"AISquadGuardTime\": -1, // -1 Means match this to AISquadPatrolTime\n                                                                          \"AISquadFollowingTime\": -1, // -1 Means match this to AISquadPatrolTime\n                                                                          \n                                                                          \"CarrierCarryDroneMax\": 4,\n                                                                          \"CarrierCarryStrikerMax\": 4,\n                                                                          \"CarrierSquadCount\": 2, // half of the total squad count of a carrier, two drone squads, two striker squads\n                                                                          \"Tooltips\": [\n                                                                            {\"Box\": \"Make Box Formation\"},\n                                                                            {\"Line\": \"Make Line Formation\"},\n                                                                            {\"Arrow\": \"Make Arrow Formation\"},\n                                                                            {\"Rectangle\": \"Make Rectangle Formation\"},\n                                                                            {\"Pyramid\": \"Make Pyramid Formation\"},\n                                                                            ],\n                                                                            \n                                                                          \n                                                                          \"Yes\": \"Yes\",\n                                                                          \"No\": \"No\",\n                                                                          \"OK\": \"OK\",\n                                                                          \"AreYouSure\": \"Are you sure?\",\n                                                                          \"AreYouSureExit\": \"Are you sure you want to exit?\",\n                                                                          \"LevelProgressLost\": \"All progress on the level will be lost\",\n                                                                          \"DeleteSquadConfirmation\": \"This will permanently delete the squad. All stats will be erased and the ships will be returned to the fleet.\",\n                                                                          \"ClearSquadConfirmation\": \"This will remove all unsaved changes to this squad.\",\n                                                                          \"LoadSquadConfirmation\": \"There are unsaved squad changes. If you load a new squad, the unsaved changes to the current squad will be lost.\",\n                                                                          \"ChooseSquadConfirmation\": \"This squad has unreplaced ships in it. It will enter the level below full strength.\",\n                                                                          \"UnchooseSquadConfirmation\": \"This will remove the squad from the list of chosen squads. It will not participate in the level.\",\n                                                                          \"GoBackConfirmation\": \"There are unsaved squad changes. If you go back to the main menu, the unsaved changes to the current squad will be lost.\",\n                                                                          \"OverCapacityAlert\": \"We can only supply so many ships for this battle. Select squad(s) within your capacity limit.\",\n                                                                          \"NoChosenSquadsAlert\": \"You must choose at least one squad to participate in the level.\",\n                                                                          \"ChoosingUnsavedSquadAlert\": \"You must save or clear the changes to this squad before you can choose it for the level.\",\n                                                                          \"ChoosingDeadSquadAlert\": \"All the ships in this squad are dead and there are no replacements left in the fleet.\",\n                                                                          \"SquadSavingStatusAlert\": \"The squad is being saved...\",\n                                                                          \"OverCapacityAlertTitle\": \"Your squads are over capacity!\",\n                                                                          \"NoChosenSquadsAlertTitle\": \"No squads chosen!\",\n                                                                          \"ChoosingUnsavedSquadAlertTitle\": \"Squad has unsaved changes!\",\n                                                                          \"ChoosingDeadSquadAlertTitle\": \"This squad has no ships left!\",\n                                                                          \"SquadSavingStatusAlertTitle\": \"Saving Squad...\",\n                                                                          \n                                                                          \n                                                                          \"VisibleBeeShipTypes\": [\"Hornet\", \"Honeybee\", \"Bumblebee\", \"Leafcutter\", \"Queen\", \"Wasp\", \"Yellow Jacket\", \"Beehive\", \"Carpenter Bee\"],\n                                                                          \"InvisibleBeeShipTypes\": [],\n                                                                          \"VisibleHumanShipTypes\": [\"Carrier\", \"Cruiser\", \"Barge\", \"Dreadnought\", \"Flagship\", \"Frigate\", \"Gunship\", \"Fire Barge\", \"Scout\", \"Factory\", \"Warp Gate\"],\n                                                                          \"InvisibleHumanShipTypes\": [],\n                                                                          \"AISide\": \"BeeSide\",\n                                                                          \"UserSide\": \"HumanSide\",\n                                                                          \"SquadMakerFirstSide\": \"HumanSide\",\n                                                                          \"SquadMakerSecondSide\": \"BeeSide\",\n                                                                          \"TotalLevels\": 10,\n                                                                          \"SquadGenerationCount\": 6\n                                                                            \n                                                                        }', '2023-07-19 09:52:52', '2025-12-19 11:52:58'),
(15, 0, 5, 'starting-settings', '{\n   \"HumanStartingShips\": [\n     {\n       \"Barge\": 50\n     },\n     {\n       \"Carrier\": 50\n     },\n     {\n       \"Cruiser\": 50\n     },\n     {\n       \"Dreadnought\": 50\n     },\n     {\n       \"Factory\": 50\n     },\n     {\n       \"Fire Barge\": 50\n     },\n     {\n       \"Flagship\": 50\n     },\n     {\n       \"Frigate\": 50\n     },\n     {\n       \"Gunship\": 50\n     },\n     {\n       \"Scout\": 50\n     },\n     {\n       \"Warp Gate\": 50\n     }\n   ],\n   \"BeeStartingShips\": [\n     {\n       \"Beehive\": 50\n     },\n     {\n       \"Bumblebee\": 50\n     },\n     {\n       \"Carpenter Bee\": 50\n     },\n     {\n       \"Honeybee\": 50\n     },\n     {\n       \"Hornet\": 50\n     },\n     {\n       \"Leafcutter\": 50\n     },\n     {\n       \"Queen\": 50\n     },\n     {\n       \"Wasp\": 50\n     },\n     {\n       \"Yellow Jacket\": 50\n     }\n   ],\n   \"HumanCampaignStartingShips\": [\n     {\n       \"Barge\": 0\n     },\n     {\n       \"Carrier\": 0\n     },\n     {\n       \"Cruiser\": 0\n     },\n     {\n       \"Dreadnought\": 0\n     },\n     {\n       \"Factory\": 0\n     },\n     {\n       \"Fire Barge\": 0\n     },\n     {\n       \"Flagship\": 0\n     },\n     {\n       \"Frigate\": 0\n     },\n     {\n       \"Gunship\": 1\n     },\n     {\n       \"Scout\": 1\n     },\n     {\n       \"Warp Gate\": 0\n     }\n   ],\n   \"BeeCampaignStartingShips\": [\n     {\n       \"Beehive\": 0\n     },\n     {\n       \"Bumblebee\": 7\n     },\n     {\n       \"Carpenter Bee\": 6\n     },\n     {\n       \"Honeybee\": 30\n     },\n     {\n       \"Hornet\": 153\n     },\n     {\n       \"Leafcutter\": 66\n     },\n     {\n       \"Queen\": 0\n     },\n     {\n       \"Wasp\": 114\n     },\n     {\n       \"Yellow Jacket\": 80\n     }\n   ],\n   \"HumanChallengeStartingShips\": [\n     {\n       \"Barge\": 5\n     },\n     {\n       \"Carrier\": 3\n     },\n     {\n       \"Cruiser\": 5\n     },\n     {\n       \"Dreadnought\": 10\n     },\n     {\n       \"Factory\": 0\n     },\n     {\n       \"Fire Barge\": 2\n     },\n     {\n       \"Flagship\": 1\n     },\n     {\n       \"Frigate\": 15\n     },\n     {\n       \"Gunship\": 20\n     },\n     {\n       \"Scout\": 30\n     },\n     {\n       \"Warp Gate\": 2\n     }\n   ],\n   \"BeeChallengeStartingShips\": [\n     {\n       \"Beehive\": 0\n     },\n     {\n       \"Bumblebee\": 0\n     },\n     {\n       \"Carpenter Bee\": 0\n     },\n     {\n       \"Honeybee\": 0\n     },\n     {\n       \"Hornet\": 0\n     },\n     {\n       \"Leafcutter\": 0\n     },\n     {\n       \"Queen\": 0\n     },\n     {\n       \"Wasp\": 0\n     },\n     {\n       \"Yellow Jacket\": 0\n     }\n   ],\n   \"SupplyCapacity\": [\n     10000,\n     10000\n   ],\n }', '2023-07-19 09:52:52', '2026-06-14 01:38:50');
INSERT INTO `settings` (`Id`, `userId`, `version`, `name`, `contents`, `created_date`, `edited_date`) VALUES
(16, 0, 5, 'ship-stats', '[\n {\n \"ShipType\": \"Barge\",\n \"Health\": 2800,\n \"Range\": [80],\n \"Power\": [300],\n \"RateOfFire\": [0],\n \"RotationRates\": [0],\n \"Speed\": 3.5,\n \"Sight\": 40,\n \"Tsv\": 95,\n \"ProjectileValue\": [.5],\n \"ProjectileTypes\": [\"None\"],\n \"WeaponSoundTypes\": [\"None\"],\n \"WeaponTypes\": [\"Bomb\"],\n \"Description\": \"The Barge is designed to take defense to the maximum. It has no weapons systems, and its bulky armor means it is one of the slowest ships in the fleet. But it can take hits better than anything.\",\n \"CodexDescription\": \"The Barge is designed to take defense to the maximum. It has no weapons systems, and its bulky armor means it is one of the slowest ships in the fleet. But it can take hits better than anything.\n \nStrategy\nThis ship is slow due to its size, so be sure to account for the time it will take to position well. Protecting high value, slower ships is where the Barge shines, as those ships won\'t be hindered too much slowing down to stay behind it. If you have Cruisers or Flagships, their survivability increases exponentially behind Barges.\n \nLore\nColloquially referred to as \\\"Bricks\\\" by Fleet personnel. Warnings have been issued to limit the nickname to the ship itself, not its personnel. These warnings became confusing when Brick Jensen was hired.\"\n \n },\n {\n \"ShipType\": \"Beacon\",\n \"Health\": 25,\n \"Range\": [],\n \"Power\": [],\n \"RateOfFire\": [],\n \"RotationRates\": [],\n \"Speed\": 0,\n \"Sight\": 60,\n \"Tsv\": 1,\n \"ProjectileValue\": [],\n \"ProjectileTypes\": [],\n \"WeaponSoundTypes\": [],\n \"WeaponTypes\": [],\n \"Description\": \"Beacons are small radars that let you track enemy movements within their range. They are deployed by Scouts and cannot move on their own.\",\n \"CodexDescription\": \"Beacons are small radars that let you track enemy movements within their range. They are deployed by Scouts and cannot move on their own.\n \nStrategy\nYou can place these in more dangerous areas where you can’t put your own ships to anticipate enemy movements. Additionally, beacons can cover your blind spots to curtail surprise attacks. On maps with obstructions, Beacons will prove useful for tracking enemy movements in bottlenecks and around corners. Be aware that they are easily destroyed, though.\n \nLore\nScout pilots have bizarrely taken to naming their beacons. Even more bizarre is that the granted names are typically just four seemingly random letters and numbers separated by a dash in the center.\n \"\n },\n {\n \"ShipType\": \"Carrier\",\n \"Health\": 1300,\n \"Range\": [],\n \"Power\": [],\n \"RateOfFire\": [],\n \"RotationRates\": [],\n \"Speed\": 4,\n \"Sight\": 40,\n \"Tsv\": 130,\n \"ProjectileValue\": [],\n \"ProjectileTypes\": [],\n \"WeaponSoundTypes\": [],\n \"WeaponTypes\": [],\n \"Description\": \"Despite carrying no weapons of its own, the Carrier is invaluable as the only way to bring Drones and Strikers into battle. As the fuel capacity for those ships is limited, they need the Carrier for refueling.\",\n \"CodexDescription\": \"Despite carrying no weapons of its own, the Carrier is invaluable as the only way to bring Drones and Strikers into battle. As the fuel capacity for those ships is limited, they need the Carrier for refueling.\n \nStrategy\nCarriers have their own production lines for Drones and Strikers, so prioritize keeping them in safety. It does not matter how many Drones and Strikers go down as long as we keep the Carrier to produce them.\n \nLore\nThe best engineers on the planet successfully fitted Carriers with full assembly lines for Drones and Strikers. These implement the latest in warp gate technology to supply raw materials. Said engineers apparently couldn’t find a way to include weapons systems.\"\n \n },\n {\n \"ShipType\": \"Cruiser\",\n \"Health\": 400,\n \"Range\": [120],\n \"Power\": [150],\n \"RateOfFire\": [2],\n \"RotationRates\": [180],\n \"Speed\": 6,\n \"Sight\": 0,\n \"Tsv\": 150,\n \"ProjectileValue\": [1.75],\n \"ProjectileTypes\": [\"None\"],\n \"WeaponSoundTypes\": [\"Beam Cannon\"],\n \"WeaponTypes\": [\"Beam Cannon\"],\n \"Description\": \"Using the latest in laser technology, cruisers are designed to have the most offensive power at range of the fleet.\",\n \"CodexDescription\": \"Using the latest in laser technology, cruisers are designed to have the most offensive power at range of the fleet.\n \nStrategy\nCruisers provide exceptional firepower at far range, but lack the speed or armor to keep themselves safe. However, these weaknesses will be mitigated if they can operate at maximum range or with more defense-oriented allies in front of them. Few ships can outrange or do more damage than a Cruiser. Its lasers will even pierce past enemy ships should it destroy them.\n \nLore\nThe windshield was redesigned to be tinted after multiple reports of temporary blindness and long-term eye damage after laser usage.\n \"\n \n },\n {\n \"ShipType\": \"Dreadnought\",\n \"Health\": 550,\n \"Range\": [80],\n \"Power\": [125],\n \"RateOfFire\": [2],\n \"RotationRates\": [150],\n \"Speed\": 9,\n \"Sight\": 0,\n \"Tsv\": 42,\n \"ProjectileValue\": [1],\n \"ProjectileTypes\": [\"Human Medium\"],\n \"WeaponSoundTypes\": [\"Light Cannon\"],\n \"WeaponTypes\": [\"Light Cannon\"], // type of turret\n \"Description\": \"The Dreadnought is the most average ship of the fleet, making it a great all-around tool for any situation. Making the most of its versatility is vital to the fleet’s success.\",\n \"CodexDescription\": \"The Dreadnought is the most average ship of the fleet, making it a great all-around tool for any situation. Making the most of its versatility is vital to the fleet’s success.\n \nStrategy\nDreadnoughts make for strong frontline ships, as they are the most durable unit with weapons systems (save for the Flagship). They provide flexibility and stability for your squads, but they need higher firepower or higher speed ships to back them up or they will eventually be taken down.\n \nLore\nDreadnought pilots and crew are among the least respected in the fleet, although not at all to do with their combat performance. Other fleet members just consider them \\\"boring.\\\"\"\n \n },\n {\n \"ShipType\": \"Drone\",\n \"Health\": 40,\n \"Range\": [40],\n \"Power\": [15],\n \"RateOfFire\": [2],\n \"RotationRates\": [306],\n \"Speed\": 25.5,\n \"Sight\": 0,\n \"Tsv\": 2,\n \"ProjectileValue\": [1],\n \"ProjectileTypes\": [\"Human Small\"],\n \"WeaponSoundTypes\": [\"Small Laser\"],\n \"WeaponTypes\": [\"Turret\"],\n \"Description\": \"Drones are extremely fast and small, due in no small part to being unmanned ships. Their pure agility is their greatest strength. Can only be escorted into battles by a Carrier.\",\n \"CodexDescription\": \"Drones are extremely fast and small, due in no small part to being unmanned ships. Their pure agility is their greatest strength. Can only be escorted into battles by a Carrier.\n \nStrategy\nDrones are very fast and very expendable. Use this to your advantage by distracting enemies with swarms of Drones while your bigger guns close in. In a pinch, Drones alone may be able to outlast powerful enemies with skilled piloting.\n \nLore\nThe low material cost and lack of need for pilots make the drone very popular with fleet accountants. Many environmentalists started protesting use of the design, however, after a large grouping of destroyed Drones were spotted in orbit around Uranus. Said environmentalists are being ignored.\"\n \n },\n {\n \"ShipType\": \"Factory\",\n \"Health\": 850,\n \"Range\": [],\n \"Power\": [],\n \"RateOfFire\": [],\n \"RotationRates\": [],\n \"Speed\": 4,\n \"Sight\": 40,\n \"Tsv\": 200,\n \"ProjectileValue\": [],\n \"ProjectileTypes\": [],\n \"WeaponSoundTypes\": [],\n \"WeaponTypes\": [],\n \"Description\": \"The Factory ship is a recent advancement in the field of asteroid mining: a mobile mining rig. Using this, we can collect the raw materials necessary for further bolstering the fleet.\n \",\n \"CodexDescription\": \"The Factory ship is a recent advancement in the field of asteroid mining: a mobile mining rig. Using this, we can collect the raw materials necessary for further bolstering the fleet.\n \nStrategy\nOnly bring factory ships when you have determined some amount of mineable asteroids on the battlefield ahead. When you do deploy these ships, make sure they’re heavily guarded, as losing them at any point will lose all the resources they’ve collected.\n \nLore\nThe factory ship isn’t a military invention, but an industrial one. It has been a popular model in the outer reaches, however, as its mobility allows for harvesting materials from asteroids. There have been many fewer deaths by mining accidents since its inception as well! Jensen Industries requested we omit the significant layoffs in the mining industry since the factory ship’s inception.\n \"\n \n },\n {\n \"ShipType\": \"Fire Barge\",\n \"Health\": 1800,\n \"Range\": [0],\n \"Power\": [2000],\n \"RateOfFire\": [0],\n \"RotationRates\": [0],\n \"Speed\": 5,\n \"Sight\": 60,\n \"Tsv\": 320,\n \"ProjectileValue\": [1.5],\n \"ProjectileTypes\": [\"None\"],\n \"WeaponSoundTypes\": [\"Fire Barge Bomb\"],\n \"WeaponTypes\": [\"Bomb\"],\n \"Description\": \"The Fire Barge is an alteration on the Barge’s design, trading a fraction of its stellar defenses for speed and frightening, single use offense. With a nuclear payload on board, it makes a great last resort against high value targets or large swarms of enemies.\",\n \"CodexDescription\": \"The Fire Barge is an alteration on the Barge’s design, trading a fraction of its stellar defenses for speed and frightening, single use offense. With a nuclear payload on board, it makes a great last resort against high value targets or large swarms of enemies.\n \nStrategy\nFire Barge explosions have a wide radius and obliterate anything in their path. This means a well placed Fire Barge can cripple the enemy fleet, and a poorly placed one can cripple ours. Do note that the same explosion will still occur should a Fire Barge be destroyed by the enemy.\n \nLore\nWhen an AI was tasked with the most efficient method to eliminate enemy fleets, it provided a similar design to the Fire Barge. It was initially denied due to high material cost and endangerment of human forces. The AI, however, redesigned it to use decommissioned Barges and be piloted entirely by itself. Despite continued reluctance from high command to use the design, the AI became obsessively devoted to piloting itself to death for the fleet, and high command relented.\n\\\"The AI pilot seems extremely disappointed every time they successfully detonate a Fire Barge, only to subsequently realize they themselves did not die with the ship. I worry about what we\'\'ve created.\\\" - Natalia Friedman, Fleet AI Technician.\"\n \n },\n {\n \"ShipType\": \"Flagship\",\n \"Health\": 1500,\n \"Range\": [30, 30, 180],\n \"Power\": [75, 75, 350],\n \"RateOfFire\": [1, 1, 3],\n \"RotationRates\": [200, 200, 100],\n \"Speed\": 4,\n \"Sight\": 0,\n \"Tsv\": 332,\n \"ProjectileValue\": [1, 1, 1.75],\n \"WeaponSoundTypes\": [\"Small Laser\", \"Small Laser\", \"Flagship Laser\"],\n \"ProjectileTypes\": [\"Human Small\", \"Human Small\", \"Flagship Shot\"],\n \"WeaponTypes\": [\"Turret\", \"Turret\", \"Full Ship Turret\"],\n \"Description\": \"The Flagship is the centerpiece of the fleet, and as such, it is appropriately powerful. Boasting state-of-the-art armor and weapons systems, this ship excels at everything but speed\",\n \"CodexDescription\": \"The Flagship is the centerpiece of the fleet, and as such, it is appropriately powerful. Boasting state-of-the-art armor and weapons systems, this ship excels at everything but speed\n \nStrategy\nThe Flagship has two weapons systems. The first, and most important, is its railgun. This fires slowly, and the Flagship must be facing its target, but it will cripple larger ships and outright destroy smaller ones. Don\'t move your flagship too much if you want to use this weapon. This weapon also has the furthest range of any other observed. The second weapons systems are close range turrets, meant mostly for self-defense. These are fully rotational and surprisingly powerful.\n \nLore\nThe Flagship is by far the best equipped ship in the Fleet, sporting all the latest advancements in weapons, engines, and defense systems. Fleet personnel all aim to be promoted to a Flagship someday, although many claim it’s due to the on-board cafeteria more than anything else.\"\n \n },\n {\n \"ShipType\": \"Frigate\",\n \"Health\": 375,\n \"Range\": [40, 40],\n \"Power\": [80, 80],\n \"RateOfFire\": [2, 2],\n \"RotationRates\": [180, 180],\n \"Speed\": 12,\n \"Sight\": 0,\n \"Tsv\": 35,\n \"ProjectileValue\": [2, 2],\n \"WeaponSoundTypes\": [\"Rocket Launch\", \"Rocket Launch\"],\n \"WeaponTypes\": [\"Rocket Turret\", \"Rocket Turret\"],\n \"ProjectileTypes\": [\"Rocket\", \"Rocket\"],\n \"Description\": \"Frigates are the explosives experts of the fleet, equipped with short range rockets that can deal spread damage to a group of targets.\",\n \"CodexDescription\": \"Frigates are the explosives experts of the fleet, equipped with short range rockets that can deal spread damage to a group of targets.\n \nStrategy\nFrigates are at their best against groups of enemy ships, but these groups are usually smaller ships that outspeed them. Be patient when positioning your frigates against these groupings and you will be rewarded. \n \nLore\nFrigate pilots notably went on strike after the introduction of Strikers to the Fleet arsenal in 2987, preemptively wanting to avoid replacement by AI. An agreement was signed wherein Strikers would only be allowed to carry \\\"worse\\\" bombs. While the pilots union was proud of this success, it should be noted that Strikers were never designed to carry any bigger or better bombs.\"\n \n },\n {\n \"ShipType\": \"Gunship\",\n \"Health\": 300,\n \"Range\": [40],\n \"Power\": [60],\n \"RateOfFire\": [2.5],\n \"RotationRates\": [240],\n \"Speed\": 18.75,\n \"Sight\": 0,\n \"Tsv\": 18,\n \"ProjectileValue\": [1],\n \"WeaponSoundTypes\": [\"Small Laser\"],\n \"WeaponTypes\": [\"Dual Cannon\"],\n \"ProjectileTypes\": [\"Human Small\"],\n \"Description\": \"Engineered to be quick and highly effective at taking out singular targets, gunships are the fleet’s premier dogfighters. \",\n \"CodexDescription\": \"Engineered to be quick and highly effective at taking out singular targets, gunships are the fleet’s premier dogfighters. \n \nStrategy\nGunships are designed for single combat, or as close to single combat as spaceship fleets can manage. This makes them a strong option for hunting down isolated enemies, but they cannot survive long if too many enemies take notice. They outspeed most ships, but a select few can chase them down.\n \nLore\nGunship pilots are the most reprimanded subset of Fleet personnel, with the most common infraction being usage of aviator sunglasses not approved for dress code in the Fleet Handbook (Article 14, Subsection E).\"\n \n },\n {\n \"ShipType\": \"Human Target\",\n \"Health\": 10000000, // 10m\n \"Range\": [],\n \"Power\": [],\n \"RateOfFire\": [],\n \"RotationRates\": [],\n \"Speed\": 0,\n \"Sight\": 0,\n \"Tsv\": 5000000, // 5m\n \"ProjectileValue\": [],\n \"WeaponSoundTypes\": [],\n \"WeaponTypes\": [],\n \"ProjectileTypes\": [],\n \"Description\": \"\",\n \"CodexDescription\": \"\"\n \n },\n {\n \"ShipType\": \"Scout\",\n \"Health\": 50,\n \"Range\": [],\n \"Power\": [],\n \"RateOfFire\": [],\n \"RotationRates\": [],\n \"Speed\": 21,\n \"Sight\": 80,\n \"Tsv\": 7,\n \"ProjectileValue\": [],\n \"ProjectileTypes\": [],\n \"WeaponSoundTypes\": [],\n \"WeaponTypes\": [],\n \"Description\": \"Scouts are frail, non combat units given the specific purpose to provide information on the battlefield. As such, they are the fastest independent ship in the fleet and have the most advanced radars, giving them unparalleled vision over enemy movements.\",\n \"CodexDescription\": \"Scouts are frail, non combat units given the specific purpose to provide information on the battlefield. As such, they are the fastest independent ship in the fleet and have the most advanced radars, giving them unparalleled vision over enemy movements.\n \nStrategy\nInformation is power, and Scouts provide just that. Given their speed, it will be difficult for enemy ships to pin them down as long as they stay moving. Once your fleet is in the heat of battle, Scouts should move to a safe location or be kept inside of a larger squad, since they lack combat capabilities. Be sure to only bring them on missions where visibility is limited, as they\'ll have no use otherwise.\n \nLore\nThese models are redesigned racing ships used in various circuits all over the solar system. While other, more advanced methods exist for tracking ships, this is by far the most reliable. \\\"Espionage and hacking are far less effective against enemies who speak neither English nor C#. This method of scouting is old school, but necessary.\\\" - Ned Feckland, Chief Intelligence Officer.\"\n \n },\n {\n \"ShipType\": \"Striker\",\n \"Health\": 300,\n \"Range\": [0],\n \"Power\": [150],\n \"RateOfFire\": [0],\n \"RotationRates\": [0],\n \"Speed\": 18.75,\n \"Sight\": 40,\n \"Tsv\": 15,\n \"ProjectileValue\": [1],\n \"ProjectileTypes\": [\"None\"],\n \"WeaponSoundTypes\": [\"Bomb\"],\n \"WeaponTypes\": [\"Bomb\"],\n \"Description\": \"Strikers are slower but sturdier than Drones, and they trade their standard weapons systems for explosives. They must get on top of their target to drop bombs, but deal high damage when successful. Can only be escorted into battles by a Carrier.\",\n \"CodexDescription\": \"Strikers are slower but sturdier than Drones, and they trade their standard weapons systems for explosives. They must get on top of their target to drop bombs, but deal high damage when successful. Can only be escorted into battles by a Carrier.\n \nStrategy\nStrikers are exceptional at piling onto a large, high value target. They are significantly sturdier than Drones, meaning that they may even survive the bombing run. In this case, they must return to a Carrier to re-arm themselves. Pulling off multiple successful bombing runs with your Strikers will be devastating for your enemies.\n \nLore\nDespite being similar to Drones in many ways, these ships are remotely piloted by humans as opposed to AI piloted. For the most part, this is better, except when Carrier crews take up all of the wifi bandwidth checking social media, causing lag for the remote pilots. (This is forbidden in Article 87, Subsection B of the Fleet Handbook and should be reported to superiors if witnessed.)\"\n \n },\n {\n \"ShipType\": \"Warp Gate\",\n \"Health\": 1350,\n \"Range\": [],\n \"Power\": [],\n \"RateOfFire\": [],\n \"RotationRates\": [],\n \"Speed\": 2,\n \"Sight\": 40,\n \"Tsv\": 150,\n \"ProjectileValue\": [],\n \"ProjectileTypes\": [],\n \"WeaponSoundTypes\": [],\n \"WeaponTypes\": [],\n \"Description\": \"Warp Gates are the latest in localized teleportation technology. Bringing one of these with you gives your fleet a way to instantly escape danger.\",\n \"CodexDescription\": \"Warp Gates are the latest in localized teleportation technology. Bringing one of these with you gives your fleet a way to instantly escape danger.\n \nStrategy\nThe warp gate allows our damaged and exhausted ships a way out of intense battles. If your carriers lose all their drones and strikers, a warp gate can get them out of the action. In dire straits, you can fully retreat your fleet through a warp gate, but be wary that you will effectively be surrendering and giving up the material cost of your warp gate to do so.\n \nLore\nPhilosophers have heavily discussed whether the process of a teleporter kills any living being going through and rebuilds it on the other side, and if so, how can we tell when they are reconstructed exactly as they were. Our scientists just think it\'s really cool!\"\n \n },\n \n \n \n {\n \"ShipType\": \"Beehive\",\n \"Health\": 2400,\n \"Range\": [],\n \"Power\": [],\n \"RateOfFire\": [],\n \"RotationRates\": [],\n \"Speed\": 2,\n \"Sight\": 40,\n \"Tsv\": 320,\n \"ProjectileValue\": [],\n \"ProjectileTypes\": [],\n \"WeaponSoundTypes\": [],\n \"WeaponTypes\": [],\n \"Description\": \"The Beehive is less of a spacecraft and more of a structure. This imposing imitation of organic beehives exists as a safe haven for its fleet during battle. Other Bee ships can dock inside it to repair damages sustained during a fight.\",\n \"CodexDescription\": \"The Beehive is less of a spacecraft and more of a structure. This imposing imitation of organic beehives exists as a safe haven for its fleet during battle. Other Bee ships can dock inside it to repair damages sustained during a fight.\n \nStrategy\nMuch like the Queen, a Beehive left unchecked will pose more problems the longer a battle goes on. Stay alert for these structures as well as any enemy ships that escape your sights after taking damage. If you can demolish a Beehive while it is hosting other ships, those ships will go down with it, which is a massive win. If you can\'t, though, you will be fighting the same ships multiple times in one battle.\n \nLore\nOf all of the Bee fleet, this may be the most impressive piece of engineering. Being a moving port of sorts, it has the stability of a planet-side base and the mobility of a spacecraft.\"\n \n },\n {\n \"ShipType\": \"Bumblebee\",\n \"Health\": 900,\n \"Range\": [160],\n \"Power\": [200],\n \"RateOfFire\": [2.75],\n \"RotationRates\": [180],\n \"Speed\": 7,\n \"Sight\": 0,\n \"Tsv\": 237,\n \"ProjectileValue\": [1.5],\n \"WeaponSoundTypes\": [\"Bowtie Laser\"],\n \"ProjectileTypes\": [\"Bumblebee Shot\"],\n \"WeaponTypes\": [\"Turret\"],\n \"Description\": \"One of the most threatening ships the Bee fleet has shown. The only drawback we have ascertained of the Bumblebee is its average speed, but the pure firepower and staying power of this ship cannot be ignored, especially considering its exceptional range.\",\n \"CodexDescription\": \"One of the most threatening ships the Bee fleet has shown. The only drawback we have ascertained of the Bumblebee is its average speed, but the pure firepower and staying power of this ship cannot be ignored, especially considering its exceptional range.\n \nStrategy\nBumblebee\'s have massive range, so the question you must answer when fighting it is how to circumvent that. To that end, there are two primary solutions. The first will be fast ships that can outmaneuver it while closing distance, although this requires expert piloting. The other is deploying ships with high durability, such as the Dreadnought or Barge, to absorb the damage while they escort your offensive ships. Beware, however, that you run a high risk of losing said durable ships in the process.\n \nLore\nOur Gunship pilots seem to have their egos bruised by the superior kill count of the Bumblebees. Even more frustrating to them is that they have no way to tell if the Bumblebee pilots even care.\"\n \n },\n {\n \"ShipType\": \"Carpenter Bee\",\n \"Health\": 600,\n \"Range\": [],\n \"Power\": [],\n \"RateOfFire\": [],\n \"RotationRates\": [],\n \"Speed\": 2,\n \"Sight\": 40,\n \"Tsv\": 170,\n \"ProjectileValue\": [],\n \"ProjectileTypes\": [],\n \"WeaponSoundTypes\": [],\n \"WeaponTypes\": [],\n\"Description\": \"The resource gatherer for the Bees. This ship possesses no combat capabilities but is still uniquely valuable to their fleet, as the Factory ship is to ours.\",\n \"CodexDescription\": \"The resource gatherer for the Bees. This ship possesses no combat capabilities but is still uniquely valuable to their fleet, as the Factory ship is to ours.\n \nStrategy\nThe Carpenter Bee has no weapons, and destroying them will limit the raw materials the Bees have to work with. It is still advised to prioritize more immediately threatening ships before the Carpenter Bee.\n \nLore\nAllowing Carpenter Bees to mine contested areas will put our own Factory ships out of work. We have already received complaints, in fact, so we advise using the Factory ships when possible to avoid a miner\'s union strike.\"\n \n },\n {\n \"ShipType\": \"Honeybee\",\n \"Health\": 40,\n \"Range\": [],\n \"Power\": [],\n \"RateOfFire\": [],\n \"RotationRates\": [],\n \"Speed\": 22.5,\n \"Sight\": 100,\n \"Tsv\": 4,\n \"ProjectileValue\": [],\n \"ProjectileTypes\": [],\n \"WeaponSoundTypes\": [],\n \"WeaponTypes\": [],\n \"Description\": \"The Honeybee is built similarly to our Scouts. It is small, agile, and possesses no weaponry, so it presumably performs the same functions for the Bee fleet.\",\n \"CodexDescription\": \"The Honeybee is built similarly to our Scouts. It is small, agile, and possesses no weaponry, so it presumably performs the same functions for the Bee fleet.\n \nStrategy\nJust because the Honeybee lacks its own weapons does not mean it lacks power. If you can catch one, this will limit the enemy fleet\'s ability to anticipate our movements.\n \nLore\nFleet engineers are eager to gain access to an intact Honeybee in order to use its technology to modify their own personal vehicles. Please report this if it proves successful; this practice is specifically forbidden by the Fleet Handbook, as captured vessels are property of the United Fleet (Article 87, Subsection B).\"\n \n },\n {\n \"ShipType\": \"Hornet\",\n \"Health\": 100,\n \"Range\": [40],\n \"Power\": [20],\n \"RateOfFire\": [2],\n \"RotationRates\": [288],\n \"Speed\": 18,\n \"Sight\": 0,\n \"Tsv\": 5,\n \"ProjectileValue\": [1],\n \"ProjectileTypes\": [\"Bee Small\"],\n \"WeaponSoundTypes\": [\"Small Laser\"],\n \"WeaponTypes\": [\"Eye\"], \n \"Description\": \"Hornets travel in packs, using their numbers as their greatest advantage. These nimble ships are capable of swarming and overwhelming isolated enemies.\",\n \"CodexDescription\": \"Hornets travel in packs, using their numbers as their greatest advantage. These nimble ships are capable of swarming and overwhelming isolated enemies.\n \nStrategy\nUse ships like the Frigate and Cruiser that can damage multiple opposing spacecraft at once to efficiently deal with Hornet packs. If you notice a pack, don\'t allow your slower vessels to be swarmed.\n \nLore\nThe Hornets bear a striking resemblance to our own Drones, but they do not seem to need a Carrier to carry them into battle. Are they entirely independent spacecraft, or have we simply never seen their home ship?\"\n \n },\n {\n \"ShipType\": \"Leafcutter\",\n \"Health\": 600,\n \"Range\": [80],\n \"Power\": [60],\n \"RateOfFire\": [1.5], // This is tied to the animation (6 FPS) for the Leafcutter so it shouldn\'\'t be changed without very good reason\n \"RotationRates\": [250],\n \"Speed\": 10.5,\n \"Sight\": 0,\n \"Tsv\": 48,\n \"ProjectileValue\": [1.5],\n \"WeaponSoundTypes\": [\"Big Laser\"],\n \"ProjectileTypes\": [\"Split Shot\"],\n \"WeaponTypes\": [\"Split Shot\"],\n \"Description\": \"This ship has been noted to have a similar build to our Dreadnoughts, but with more advanced offenses. Their ammunition is able to split into smaller pieces after impacting a target, like a shrapnel blast.\",\n \"CodexDescription\": \"This ship has been noted to have a similar build to our Dreadnoughts, but with more advanced offenses. Their ammunition is able to split into smaller pieces after impacting a target, like a shrapnel blast.\n \nStrategy\nThe Leafcutter\'s shots are particularly potent fired into large groups of ships. Avoid engaging it with larger squads, particularly those made up of fragile or tightly grouped ships. Its low speed should make it reasonable to outmaneuver.\n \nLore\nWe have fielded requests from gunners assigned to Dreadnoughts asking for guns more like the Leafcutters. Gunship pilots have also specifically requested Dreadnoughts do not get this upgrade, as it would make them \\\"too cool.\\\" Either way, our engineers do not think it possible.\"\n \n },\n {\n \"ShipType\": \"Queen\",\n \"Health\": 7000,\n \"Range\": [140, 70, 70, 70, 70],\n \"Power\": [180, 30, 30, 30, 30],\n \"RateOfFire\": [1.5, .5, .5, .5, .5],\n \"RotationRates\": [125, 250, 250, 250, 250],\n \"Speed\": 4,\n \"Sight\": 200,\n \"Tsv\": 770,\n \"ProjectileValue\": [1, 1, 1, 1, 1],\n \"WeaponSoundTypes\": [\"Queen Laser\", \"Small Laser\", \"Small Laser\", \"Small Laser\", \"Small Laser\"],\n \"ProjectileTypes\": [\"Queen Large\", \"Queen Small\", \"Queen Small\", \"Queen Small\", \"Queen Small\"],\n \"WeaponTypes\": [\"Eye\", \"Queen Eye\", \"Queen Eye\", \"Queen Eye\", \"Queen Eye\"],\n \"Description\": \"The largest and most threatening of the Bee Fleet. This ship is incredibly durable and can do some serious damage to your fleet if you aren\'t careful.\",\n \"CodexDescription\": \"The largest and most threatening of the Bee Fleet. This ship is incredibly durable and can do some serious damage to your fleet if you aren\'t careful.\n \nStrategy\nThe Queen has many weapons on its large framework, so being within range is extremely dangerous. If you have access to Flagships, they can outrange the Queen, but otherwise you will need to get a powerful group of ships in range. Strikers are potent for a swift and critical blow, while high damage ships like Frigates and Cruisers are effective if escorted by more durable counterparts. Either way, do not ignore the Queen, as it produces its own Yellow Jackets. Over time it will become an unmanageable problem.\n \nLore\nFleet scientists theorize that this ship is too large for warping or high speed travels, and thus can only be built in our solar system. This provides a slight advantage, as an entire fleet of Queen Bees would have surely spelled doom for humanity. If the Bees get enough time and resources to construct more, however...\"\n \n },\n {\n \"ShipType\": \"Wasp\",\n \"Health\": 400,\n \"Range\": [40],\n \"Power\": [80],\n \"RateOfFire\": [2.5],\n \"RotationRates\": [240],\n \"Speed\": 15,\n \"Sight\": 0,\n \"Tsv\": 16,\n \"ProjectileValue\": [1],\n \"ProjectileTypes\": [\"Bee Medium\"],\n \"WeaponSoundTypes\": [\"Big Laser\"],\n \"WeaponTypes\": [\"Eye\"],\n \"Description\": \"Wasps are extremely quick vessels with a surprising amount of armor. They are one of the more common members of the Bee fleet.\",\n \"CodexDescription\": \"Wasps are extremely quick vessels with a surprising amount of armor. They are one of the more common members of the Bee fleet.\n \nStrategy\nYou will need ships that can either match the Wasp\'s speed or fire accurately enough when it does venture into their range. Thankfully, it doesn\'t hit as brutally as other enemies, so you don\'t need to go out of your way to destroy it. But outright ignoring any enemy vessel with weapons may still cause problems.\n \nLore\nThe running theory about Wasps is that they must be unmanned ships to contain the level of armor they do. Although that does raise the question of how many Bee ships can be unmanned, not to mention who is directing them.\"\n \n },\n {\n \"ShipType\": \"Yellow Jacket\",\n \"Health\": 200,\n \"Range\": [0],\n \"Power\": [200],\n \"RateOfFire\": [0],\n \"RotationRates\": [0],\n \"Speed\": 19.5,\n \"Sight\": 40,\n \"Tsv\": 11,\n \"ProjectileValue\": [1],\n \"ProjectileTypes\": [\"None\"],\n \"WeaponSoundTypes\": [\"None\"],\n \"WeaponTypes\": [\"Bomb\"],\n \"WeaponTypes\": [\"Bomb\"],\n \"Description\": \"Yellow Jackets are packed with strong engines and stronger explosives, making a very dangerous foe. On the admittedly grim bright side, their payload can only be delivered once.\",\n \"CodexDescription\": \"Yellow Jackets are packed with strong engines and stronger explosives, making a very dangerous foe. On the admittedly grim bright side, their payload can only be delivered once.\n \nStrategy\nYellow Jackets are specifically designed to be suicide bombers, and they are extremely adept at the job. Do your best to take the frail vessel down before it can reach you, or you may suffer intense damages to your fleet. If necessary, play keepaway with your faster vessels in order to preserve your slower ships.\n \nLore\nThis kamikaze ship has an intentional design to it, leading us to believe that our enemy has either enough resources for remote controlled, one-time-use ships or enough fervor to sacrifice their own people. Both are terrifying possibilities.\"\n \n }\n ]', '2023-07-19 09:52:52', '2025-09-21 09:00:52');
