(17050, 2, 'campaign_levels_data', '{\"Levels\":[{\"Id\":0,\"Side\":1,\"Name\":\"Anomaly\",\"MapIndex\":0,\"Obstacles\":\"No\",\"ObstacleList\":[],\"AsteroidOption\":0,\"FogOfWar\":1,\"Mining\":0,\"HasPreLevelIntro\":false,\"HasSquadActionBox\":false,\"SupplyCapacity\":25,\"EnemyReinforcementsOption\":0,\"EnemyReinforcementDelay\":0,\"EnemyReinforcements\":[],\"EnemySquads\":[],\"EnemyExistingSquads\":[],\"EnemyReport\":\"\",\"UserStartingPosition\":{\"x\":0,\"y\":0},\"AIStartingPosition\":{\"x\":0,\"y\":0}},{\"Id\":1,\"Side\":1,\"Name\":\"Reinforcements\",\"MapIndex\":0,\"Obstacles\":\"No\",\"ObstacleList\":[],\"AsteroidOption\":0,\"FogOfWar\":1,\"Mining\":0,\"HasPreLevelIntro\":true,\"HasSquadActionBox\":true,\"SupplyCapacity\":250,\"EnemyReinforcementsOption\":0,\"EnemyReinforcementDelay\":0,\"EnemyReinforcements\":[],\"EnemySquads\":[],\"EnemyExistingSquads\":[],\"EnemyReport\":\"\",\"UserStartingPosition\":{\"x\":5,\"y\":10},\"AIStartingPosition\":{\"x\":0,\"y\":230}},{\"Id\":2,\"Side\":1,\"Name\":\"Pushback\",\"MapIndex\":0,\"Obstacles\":\"Pushback\",\"ObstacleList\":[],\"AsteroidOption\":0,\"FogOfWar\":0,\"Mining\":0,\"HasPreLevelIntro\":true,\"HasSquadActionBox\":true,\"SupplyCapacity\":324,\"EnemyReinforcementsOption\":0,\"EnemyReinforcementDelay\":0,\"EnemyReinforcements\":[],\"EnemySquads\":[],\"EnemyExistingSquads\":[],\"EnemyReport\":\"We\\u0027ve spotted a large gathering of several Bees near Pluto. It\\u0027s not nearly their full fleet so we have a chance to elimnate them if we act quickly.\",\"UserStartingPosition\":{\"x\":5,\"y\":-200},\"AIStartingPosition\":{\"x\":0,\"y\":230}},{\"Id\":3,\"Side\":1,\"Name\":\"Bluer Pastures\",\"MapIndex\":0,\"Obstacles\":\"Bluer Pastures\",\"ObstacleList\":[],\"AsteroidOption\":0,\"FogOfWar\":0,\"Mining\":0,\"HasPreLevelIntro\":true,\"HasSquadActionBox\":true,\"SupplyCapacity\":324,\"EnemyReinforcementsOption\":0,\"EnemyReinforcementDelay\":0,\"EnemyReinforcements\":[],\"EnemySquads\":[],\"EnemyExistingSquads\":[],\"EnemyReport\":\"We expect large numbers of the Hornets, Honeybees, and Wasps we\\u0027ve seen already but we aren\\u0027t certain on the exact fleet size. There are also several unidentified ships we haven\\u0027t seen yet.\",\"UserStartingPosition\":{\"x\":35,\"y\":10},\"AIStartingPosition\":{\"x\":0,\"y\":230}},{\"Id\":4,\"Side\":1,\"Name\":\"Seize the Means\",\"MapIndex\":1,\"Obstacles\":\"No\",\"ObstacleList\":[],\"AsteroidOption\":0,\"FogOfWar\":0,\"Mining\":1,\"HasPreLevelIntro\":true,\"HasSquadActionBox\":true,\"SupplyCapacity\":500,\"EnemyReinforcementsOption\":0,\"EnemyReinforcementDelay\":0,\"EnemyReinforcements\":[],\"EnemySquads\":[],\"EnemyExistingSquads\":[],\"EnemyReport\":\"The Scouts have reported movement but that\\u0027s all we know.\",\"UserStartingPosition\":{\"x\":-400,\"y\":0},\"AIStartingPosition\":{\"x\":0,\"y\":230}},{\"Id\":5,\"Side\":1,\"Name\":\"Of Production!\",\"MapIndex\":1,\"Obstacles\":\"No\",\"ObstacleList\":[],\"AsteroidOption\":0,\"FogOfWar\":0,\"Mining\":1,\"HasPreLevelIntro\":true,\"HasSquadActionBox\":true,\"SupplyCapacity\":1500,\"EnemyReinforcementsOption\":0,\"EnemyReinforcementDelay\":0,\"EnemyReinforcements\":[],\"EnemySquads\":[],\"EnemyExistingSquads\":[],\"EnemyReport\":\"We don\\u0027t think there are any Bees in our immedate vicinity but there are Bees all around Neptune so we could be attacked at any time. There are lots of rich asteroids around so we\\u0027ll want to bring in the Factories.\",\"UserStartingPosition\":{\"x\":-200,\"y\":0},\"AIStartingPosition\":{\"x\":480,\"y\":0}},{\"Id\":6,\"Side\":1,\"Name\":\"Pressing Forward\",\"MapIndex\":1,\"Obstacles\":\"Pressing Forward\",\"ObstacleList\":[],\"AsteroidOption\":0,\"FogOfWar\":0,\"Mining\":0,\"HasPreLevelIntro\":true,\"HasSquadActionBox\":true,\"SupplyCapacity\":1000,\"EnemyReinforcementsOption\":0,\"EnemyReinforcementDelay\":0,\"EnemyReinforcements\":[],\"EnemySquads\":[],\"EnemyExistingSquads\":[],\"EnemyReport\":\"We\\u0027ve found a weak spot with a smaller number of Bees. We need to punch a hole in the blockade that we can get through.\",\"UserStartingPosition\":{\"x\":-200,\"y\":0},\"AIStartingPosition\":{\"x\":480,\"y\":0}},{\"Id\":7,\"Side\":1,\"Name\":\"Minesweeper\",\"MapIndex\":2,\"Obstacles\":\"Minesweeper\",\"ObstacleList\":[],\"AsteroidOption\":0,\"FogOfWar\":1,\"Mining\":0,\"HasPreLevelIntro\":true,\"HasSquadActionBox\":true,\"SupplyCapacity\":300,\"EnemyReinforcementsOption\":0,\"EnemyReinforcementDelay\":0,\"EnemyReinforcements\":[],\"EnemySquads\":[],\"EnemyExistingSquads\":[],\"EnemyReport\":\"We know there are bee patrols, but we can\\u0027t say for certain what types of ships we\\u0027re up against\",\"UserStartingPosition\":{\"x\":175,\"y\":-225},\"AIStartingPosition\":{\"x\":0,\"y\":0}},{\"Id\":8,\"Side\":1,\"Name\":\"Bee-noculars\",\"MapIndex\":2,\"Obstacles\":\"Bee-noculars\",\"ObstacleList\":[],\"AsteroidOption\":0,\"FogOfWar\":0,\"Mining\":0,\"HasPreLevelIntro\":true,\"HasSquadActionBox\":true,\"SupplyCapacity\":500,\"EnemyReinforcementsOption\":0,\"EnemyReinforcementDelay\":0,\"EnemyReinforcements\":[],\"EnemySquads\":[],\"EnemyExistingSquads\":[],\"EnemyReport\":\"We know there\\u0027s a scattering of Bees, including some ships we don\\u0027t recognize, but otherwise we\\u0027re flying dark.\",\"UserStartingPosition\":{\"x\":450,\"y\":450},\"AIStartingPosition\":{\"x\":480,\"y\":0}},{\"Id\":9,\"Side\":1,\"Name\":\"On the Offensive\",\"MapIndex\":2,\"Obstacles\":\"On the Offensive\",\"ObstacleList\":[],\"AsteroidOption\":0,\"FogOfWar\":1,\"Mining\":0,\"HasPreLevelIntro\":true,\"HasSquadActionBox\":true,\"SupplyCapacity\":500,\"EnemyReinforcementsOption\":0,\"EnemyReinforcementDelay\":0,\"EnemyReinforcements\":[],\"EnemySquads\":[],\"EnemyExistingSquads\":[],\"EnemyReport\":\"We know there\\u0027s a scattering of Bees, including some ships we don\\u0027t recognize, but otherwise we\\u0027re flying dark.\",\"UserStartingPosition\":{\"x\":450,\"y\":450},\"AIStartingPosition\":{\"x\":480,\"y\":0}},{\"Id\":10,\"Side\":1,\"Name\":\"On the Defensive\",\"MapIndex\":2,\"Obstacles\":\"On the Defensive\",\"ObstacleList\":[],\"AsteroidOption\":0,\"FogOfWar\":0,\"Mining\":1,\"HasPreLevelIntro\":true,\"HasSquadActionBox\":true,\"SupplyCapacity\":2000,\"EnemyReinforcementsOption\":0,\"EnemyReinforcementDelay\":0,\"EnemyReinforcements\":[],\"EnemySquads\":[],\"EnemyExistingSquads\":[],\"EnemyReport\":\"There aren\\u0027t any Bees around right now but we know there are many close by and they may close in on us.\",\"UserStartingPosition\":{\"x\":-200,\"y\":-200},\"AIStartingPosition\":{\"x\":450,\"y\":450}},{\"Id\":11,\"Side\":1,\"Name\":\"A New Threat\",\"MapIndex\":2,\"Obstacles\":\"No\",\"ObstacleList\":[],\"AsteroidOption\":0,\"FogOfWar\":0,\"Mining\":0,\"HasPreLevelIntro\":true,\"HasSquadActionBox\":true,\"SupplyCapacity\":1000,\"EnemyReinforcementsOption\":0,\"EnemyReinforcementDelay\":0,\"EnemyReinforcements\":[],\"EnemySquads\":[],\"EnemyExistingSquads\":[],\"EnemyReport\":\"We\\u0027ve spotted some Bees further out moving very slowly. That\\u0027s all we know\",\"UserStartingPosition\":{\"x\":-200,\"y\":-200},\"AIStartingPosition\":{\"x\":450,\"y\":450}}]}', '2025-05-27 09:52:10', '2026-08-14 15:08:17'),
